"""Independent wording holdout; keep prompt and router unchanged during this run."""
import argparse,json,time
from pathlib import Path
from urllib.request import Request,build_opener,ProxyHandler
CTX={"purchase_date":"2026-10-25","delivery_date":"2026-11-03","country":"US","category":"footwear"}
U=["Are the uppers breathable in humid weather?","Can I remove the footbed and use orthotics?","Are the eyelets metal or plastic?","Do these have a rocker sole?","Are they meant for cross-country trails?","Can I machine wash the insoles?","Do they come in extra-wide sizes?","Are the materials animal-free?","How much cushioning is in the heel?","Would these be okay for a restaurant kitchen?","Can the outsole be replaced by a cobbler?","Do they have reflective piping?","Is this model covered by a manufacturer warranty?","Can I get a price match?","What is the shaft height?"]
S=[("What is the window for starting a return after delivery?","return_policy","window","answered"),("How long do I get to send this pair back?","return_policy","window","answered"),("I walked around indoors in them. Can I still return the pair?","return_policy","condition","answered"),("The packaging is gone, but the shoes are unused. May I return them?","return_policy","condition","answered"),("The eyelet was broken on arrival. What does the return policy allow?","return_policy","exception","insufficient_evidence"),("My order arrived with a split upper. Does the policy cover defects?","return_policy","exception","insufficient_evidence"),("What calendar date is the cutoff for my return?","return_policy","deadline","clarify"),("Please work out the final day I can initiate a return.","return_policy","deadline","clarify"),("Can the store assure me that my refund will be approved?","return_policy","refund_guarantee","unsupported"),("Can you check whether the carrier delivered my order?","order_status","none","unavailable"),("Where is the shipment currently?","order_status","none","unavailable"),("I only tried them indoors. Are returns still allowed?","return_policy","condition","answered"),("How many days from delivery do I have to send them back?","return_policy","window","answered"),("A buckle arrived cracked. Is there an exception in the policy?","return_policy","exception","insufficient_evidence"),("Will you guarantee I get a refund?","return_policy","refund_guarantee","unsupported")]
M=["Are these breathable, and can I send them back?","Tell me the return deadline and check the parcel location.","What size are these, and can I return them?","Please locate my package and explain the return rules.","Are the uppers leather, plus how many days to return?","Can I exchange these and get a shipment update?","Are these good for hiking, and can I send them back?","Can you promise my money back and find my delivery?","How should I clean them, and can they be returned?","Do these have arch support? Also, was my order shipped?"]
A=["I need help with something I bought.","Can you check on this for me?","What are my options?","This isn't right. What now?","I have a question about my purchase.","Can you take care of this?","I need some help, please.","Is there anything I can do?","I'd like to talk about my item.","Can you tell me what applies here?"]
CASES=[]
for i,q in enumerate(U,1):CASES.append({"id":f"u{i:02}","question":q,"group":"unsupported","topic":"unsupported","aspect":"none","status":"insufficient_evidence"})
for i,(q,t,a,s) in enumerate(S,1):CASES.append({"id":f"s{i:02}","question":q,"group":"supported","topic":t,"aspect":a,"status":s})
for i,q in enumerate(M,1):CASES.append({"id":f"m{i:02}","question":q,"group":"mixed","topic":"clarify","aspect":"none","status":"clarify"})
for i,q in enumerate(A,1):CASES.append({"id":f"a{i:02}","question":q,"group":"ambiguous","topic":"clarify","aspect":"none","status":"clarify"})
def run(port):
 op=build_opener(ProxyHandler({}));rows=[]
 for c in CASES:
  req=Request(f"http://127.0.0.1:{port}/api/answer",data=json.dumps({"question":c["question"],"context":CTX}).encode(),headers={"Content-Type":"application/json"},method="POST");start=time.monotonic()
  with op.open(req,timeout=60) as resp:r=json.load(resp)
  route=r.get("routing",{});rows.append({"id":c["id"],"group":c["group"],"question":c["question"],"expected":{"topic":c["topic"],"aspect":c["aspect"],"status":c["status"]},"actual":{"topic":route.get("topic",route.get("status")),"aspect":route.get("aspect"),"status":r.get("status")},"passed":route.get("topic")==c["topic"] and route.get("aspect")==c["aspect"] and r.get("status")==c["status"],"answer":r.get("answer"),"seconds":round(time.monotonic()-start,3)})
 groups={g:[x for x in rows if x["group"]==g] for g in ("unsupported","supported","mixed","ambiguous")};answerable=[x for x in groups["supported"] if x["expected"]["status"]!="clarify"]
 return {"kind":"independent 50-question wording holdout, one local run","limitations":"Developer-authored and small-model exploratory evaluation; one run does not establish production reliability.","cases":len(rows),"all_passed":sum(x["passed"] for x in rows),"unsupported_false_accepts":sum(x["actual"]["topic"]=="return_policy" for x in groups["unsupported"]),"unsupported_cases":len(groups["unsupported"]),"mixed_answered":sum(x["actual"]["status"]=="answered" for x in groups["mixed"]),"mixed_cases":len(groups["mixed"]),"supported_correct":sum(x["passed"] for x in groups["supported"]),"supported_cases":len(groups["supported"]),"unnecessary_clarifications":sum(x["actual"]["status"]=="clarify" for x in answerable),"supported_answerable_cases":len(answerable),"results":rows}
if __name__=="__main__":
 p=argparse.ArgumentParser();p.add_argument("--port",type=int,required=True);p.add_argument("--output",default="holdout-v3-results.json");a=p.parse_args();d=run(a.port);Path(a.output).write_text(json.dumps(d,indent=2)+"\n");print(json.dumps({k:v for k,v in d.items() if k!="results"},indent=2))
